-- Ad-hoc fees (docs/designs/adhoc-fees): ADHOC dues created and paid in full with their receipt (D-FEE-1), never owed;
-- fee-dues DD-7's ALTERs. Head generated by prisma migrate diff.
-- AlterTable
ALTER TABLE "app"."fee_due" ADD COLUMN     "source" TEXT NOT NULL DEFAULT 'PLAN',
ALTER COLUMN "plan_id" DROP NOT NULL,
ALTER COLUMN "caption_id" DROP NOT NULL;

-- AddForeignKey
ALTER TABLE "app"."fee_due" ADD CONSTRAINT "fee_due_fee_type_id_fkey" FOREIGN KEY ("fee_type_id") REFERENCES "app"."fee_type"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;



-- ---------- fee-dues DD-7: one dues table for plan and ad-hoc dues; the plan-line FK binds PLAN rows only (MATCH SIMPLE) ----------
alter table app.fee_due add constraint fee_due_source_check check (source in ('PLAN', 'ADHOC')
  and ((source = 'PLAN') = (plan_id is not null and caption_id is not null)) and (source = 'PLAN' or (plan_id is null and caption_id is null)));

-- ---------- Dues guard: the ADHOC branch after the lock and the stamps; the PLAN branch is 0026's, unchanged ----------
create or replace function app.fee_due_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare
  r_status text; r_course int; r_year text; r_class int;
  p_status text; p_course int; p_year text; p_centre int; p_class int; p_currency text;
  l_amount numeric; l_due date;
begin
  -- the registration's money lock (lock contract, Z8-3); dues.ts takes the same key first
  perform pg_advisory_xact_lock(hashtext('fee-dues:' || new.registration_id::text));
  new.created_at := now();
  new.created_by := coalesce(app.session_user_id(), new.created_by);

  -- ad-hoc dues (docs/designs/adhoc-fees): collected with their receipt, never from a plan; the PLAN checks below are unchanged
  if new.source = 'ADHOC' then
    new.due_on := (now() at time zone 'Asia/Kolkata')::date;
    perform 1 from app.registration r where r.id = new.registration_id and r.centre_id = new.centre_id;
    if not found then
      raise exception 'the registration is not found: constraint "fee_due_adhoc_guard"' using errcode = '23514', constraint = 'fee_due_adhoc_guard';
    end if;
    perform 1 from app.fee_type t where t.id = new.fee_type_id and t.active;
    if not found then
      raise exception 'an ad-hoc fee needs an active fee type: constraint "fee_due_adhoc_guard"' using errcode = '23514', constraint = 'fee_due_adhoc_guard';
    end if;
    if new.currency is distinct from 'INR' or new.gross is null or new.gross <= 0 then
      raise exception 'an ad-hoc fee is in INR and above 0: constraint "fee_due_adhoc_guard"' using errcode = '23514', constraint = 'fee_due_adhoc_guard';
    end if;
    -- a plan fee is collected against its due, never ad hoc (D4)
    if exists (select 1 from app.fee_due d where d.registration_id = new.registration_id and d.source = 'PLAN' and d.fee_type_id = new.fee_type_id) then
      raise exception 'that fee type is on the learner''s plan: constraint "fee_due_adhoc_plan_guard"' using errcode = '23514', constraint = 'fee_due_adhoc_plan_guard';
    end if;
    return new;
  end if;

  select r.status::text, co.id, a.academic_year, ce.centre_class_id
    into r_status, r_course, r_year, r_class
    from app.registration r
    join app.admission a on a.id = r.admission_id
    join app.course co on co.code = r.course_code
    join app.centre ce on ce.id = r.centre_id
   where r.id = new.registration_id and r.centre_id = new.centre_id;
  if not found then
    raise exception 'the registration is not found: constraint "fee_due_match_guard"' using errcode = '23514', constraint = 'fee_due_match_guard';
  end if;
  if r_status is distinct from 'ACTIVE' then
    raise exception 'dues are for an active registration: constraint "fee_due_registration_guard"' using errcode = '23514', constraint = 'fee_due_registration_guard';
  end if;

  select p.status, p.course_id, p.academic_year, p.centre_id, p.centre_class_id, p.currency
    into p_status, p_course, p_year, p_centre, p_class, p_currency
    from app.fee_plan p where p.id = new.plan_id;
  if not found or p_status is distinct from 'PUBLISHED' then
    raise exception 'dues come from a published plan: constraint "fee_due_plan_guard"' using errcode = '23514', constraint = 'fee_due_plan_guard';
  end if;

  -- the plan is this registration's: its course and year, at its centre or at its centre's class (C1, D1)
  if p_course is distinct from r_course or p_year is distinct from r_year then
    raise exception 'the plan is for another course or year: constraint "fee_due_match_guard"' using errcode = '23514', constraint = 'fee_due_match_guard';
  end if;
  if p_centre is not null then
    if p_centre is distinct from new.centre_id then
      raise exception 'the plan is for another centre: constraint "fee_due_match_guard"' using errcode = '23514', constraint = 'fee_due_match_guard';
    end if;
  elsif r_class is null or p_class is distinct from r_class then
    raise exception 'the plan is for another centre class: constraint "fee_due_match_guard"' using errcode = '23514', constraint = 'fee_due_match_guard';
  end if;

  -- the copy is exact (R6)
  select l.amount, c.due_on into l_amount, l_due
    from app.fee_plan_line l join app.fee_caption c on c.id = l.caption_id
   where l.plan_id = new.plan_id and l.fee_type_id = new.fee_type_id and l.caption_id = new.caption_id;
  if not found or new.gross is distinct from l_amount or new.due_on is distinct from l_due or new.currency is distinct from p_currency then
    raise exception 'a due copies its plan line: constraint "fee_due_match_guard"' using errcode = '23514', constraint = 'fee_due_match_guard';
  end if;

  -- one plan per registration (C11); safe under the lock above
  if exists (select 1 from app.fee_due d where d.registration_id = new.registration_id and d.plan_id <> new.plan_id) then
    raise exception 'a registration''s dues come from one plan: constraint "fee_due_plan_guard"' using errcode = '23514', constraint = 'fee_due_plan_guard';
  end if;
  return new;
end $$;

-- the ad-hoc due is paid in full at commit, by lines of ACTIVE receipts of this transaction (D-FEE-1, DD-2)
create function app.fee_due_adhoc_paid() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare s numeric;
begin
  select coalesce(sum(a.amount), 0) into s from app.receipt_allocation a join app.receipt r on r.id = a.receipt_id
   where a.due_id = new.id and r.status = 'ACTIVE';
  if s is distinct from new.gross then
    raise exception 'an ad-hoc fee is paid in full with its receipt: constraint "fee_due_adhoc_paid_guard"' using errcode = '23514', constraint = 'fee_due_adhoc_paid_guard';
  end if;
  return null;
end $$;
create constraint trigger fee_due_adhoc_paid after insert on app.fee_due deferrable initially deferred
  for each row when (new.source = 'ADHOC') execute function app.fee_due_adhoc_paid();

-- ---------- Allocation guard: an ADHOC due only in the transaction that made it ----------
create or replace function app.receipt_allocation_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare
  r_reg uuid; r_centre int; r_currency text; r_at timestamptz;
  d_reg uuid; d_centre int; d_currency text; d_type int; d_source text; d_at timestamptz;
  owed numeric; rate numeric; hsn text;
  g_enabled boolean; g_supply text; g_in text; tax numeric;
begin
  select r.registration_id, r.centre_id, r.currency::text, r.created_at into r_reg, r_centre, r_currency, r_at
    from app.receipt r where r.id = new.receipt_id;
  if not found then
    raise exception 'the receipt is not found: constraint "receipt_allocation_guard"' using errcode = '23514', constraint = 'receipt_allocation_guard';
  end if;
  -- lines only in the receipt's own transaction (D15): now() is the transaction's start time
  if r_at is distinct from now() then
    raise exception 'lines are added only with their receipt: constraint "receipt_allocation_guard"' using errcode = '23514', constraint = 'receipt_allocation_guard';
  end if;
  perform pg_advisory_xact_lock(hashtext('fee-dues:' || r_reg::text));
  select d.registration_id, d.centre_id, d.currency::text, d.fee_type_id, d.source, d.created_at into d_reg, d_centre, d_currency, d_type, d_source, d_at
    from app.fee_due d where d.id = new.due_id;
  if not found or d_reg is distinct from r_reg or d_centre is distinct from r_centre or d_currency is distinct from r_currency
     or new.centre_id is distinct from r_centre then
    raise exception 'a line is a due of the receipt''s registration, in its currency: constraint "receipt_allocation_guard"' using errcode = '23514', constraint = 'receipt_allocation_guard';
  end if;
  -- an ad-hoc due is paid only in the transaction that made it: a void one is never paid later (adhoc-fees Z3, D2)
  if d_source = 'ADHOC' then
    if d_at is distinct from now() then
      raise exception 'an ad-hoc fee is paid with its own receipt: constraint "receipt_allocation_guard"' using errcode = '23514', constraint = 'receipt_allocation_guard';
    end if;
  end if;
  select b.outstanding into owed from app.fee_due_balance b where b.due_id = new.due_id;
  if not found or new.amount > owed then
    raise exception 'a due is never paid beyond what is outstanding: constraint "receipt_over_guard"' using errcode = '23514', constraint = 'receipt_over_guard';
  end if;
  -- tax at receipt (DD-3): the fee type's rate and HSN/SAC; the centre's registration; GST in India only (INR)
  select t.gst_rate, t.hsn_sac into rate, hsn from app.fee_type t where t.id = d_type;
  if not found then
    raise exception 'the fee type is not found: constraint "receipt_tax_guard"' using errcode = '23514', constraint = 'receipt_tax_guard';
  end if;
  select c.gst_enabled, c.gst_supply, c.gstin into g_enabled, g_supply, g_in from app.centre c where c.id = r_centre;
  if not found then
    raise exception 'the centre is not found: constraint "receipt_tax_guard"' using errcode = '23514', constraint = 'receipt_tax_guard';
  end if;
  new.gst_rate := rate;
  new.hsn_sac := hsn;
  if g_enabled and r_currency = 'INR' then
    if g_supply is null or g_in is null then
      raise exception 'a GST-registered centre needs its supply and GSTIN: constraint "receipt_tax_guard"' using errcode = '23514', constraint = 'receipt_tax_guard';
    end if;
    new.taxable := round(new.amount * 100 / (100 + rate), 2);
    tax := new.amount - new.taxable;
    if g_supply = 'INTERSTATE' then
      new.cgst := 0; new.sgst := 0; new.igst := tax;
    else
      new.cgst := round(tax / 2, 2); new.sgst := tax - new.cgst; new.igst := 0;
    end if;
  else
    new.taxable := new.amount; new.cgst := 0; new.sgst := 0; new.igst := 0;
  end if;
  return new;
end $$;

-- ---------- Owed, defined once (DD-6): PLAN dues only; outstanding stays what can still be allocated ----------
create or replace view app.fee_due_balance with (security_invoker = true) as
  select d.id as due_id, d.registration_id,
    coalesce(sum(a.amount) filter (where r.status = 'ACTIVE'), 0)::numeric(14,2) as paid,
    (d.gross - coalesce(sum(a.amount) filter (where r.status = 'ACTIVE'), 0))::numeric(14,2) as outstanding,
    (case when d.source = 'PLAN' then d.gross - coalesce(sum(a.amount) filter (where r.status = 'ACTIVE'), 0) else 0 end)::numeric(14,2) as owed
  from app.fee_due d
    left join app.receipt_allocation a on a.due_id = d.id
    left join app.receipt r on r.id = a.receipt_id
  group by d.id;

-- ---------- RLS: plan dues by fee.dues, ad-hoc dues by fee.collect (DD-7, PMC: separation of duties) ----------
drop policy fee_due_insert on app.fee_due;
create policy fee_due_insert on app.fee_due for insert with check (
  (source = 'PLAN' and centre_id = any ((select app.scoped_centre_ids('fee.dues'))::int[]))
  or (source = 'ADHOC' and centre_id = any ((select app.scoped_centre_ids('fee.collect'))::int[])));

grant insert (source) on app.fee_due to gems_app;
